window.MOTIF_CATALOG_CHUNKS[11]={"cards":[{"id":"ML-T01139","row_version":2,"title":"괴수","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01130","tag_path":[],"summary":"괴수는 압도적인 크기나 파괴력으로 환경과 사회에 재난 규모의 위협을 주는 생명체다. 거대하고 재난적인 존재 방식이 중심일 때 적용하며, 크기만 큰 동물이나 특정 종족명이 확립된 괴물과 구분한다.","accent":"#62816F","tab":"#528982","facet":"존재·종족","bookmark":"괴수","entry_url":"cards/ML-T01139/index.html"},{"id":"ML-T01140","row_version":2,"title":"인공 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"group","parent_id":"ML-F12","tag_path":[],"summary":"인공 존재는 설계·제작·조립 등 의도적인 인위 과정을 통해 존재하게 된 개체다. 만들어진 기원이 핵심이며, 자연 생명에 기술적 강화를 더한 경우나 단순한 도구에는 적용하지 않는다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"인공 존재","entry_url":"cards/ML-T01140/index.html"},{"id":"ML-T01141","row_version":3,"title":"로봇","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"로봇은 기계 부품과 제어 체계를 바탕으로 작동하는 자동화된 기계 존재다. 자율성의 정도와 무관하게 기계적 구조가 중심이며, 인간형 외모나 인간 수준의 인격이 설정되면 안드로이드와 함께 판단할 수 있다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"로봇","entry_url":"cards/ML-T01141/index.html"},{"id":"ML-T01142","row_version":2,"title":"안드로이드","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"안드로이드는 인간과 유사한 외형이나 행동을 갖도록 만든 인공 존재다. 인간형 몸과 인간 모방이 특징이며, 외형과 무관하게 기계 작업만 수행하는 로봇과 구분한다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"안드로이드","entry_url":"cards/ML-T01142/index.html"},{"id":"ML-T01143","row_version":5,"title":"사이보그","original":"Cyborg","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"살아 있는 몸에 기계 부품과 제어 장치가 결합해 두 체계가 함께 움직이는 존재다. 몸의 경계와 정체성, 능력의 변화가 서사의 소재가 된다. 기계화된 몸을 항해에 특별히 활용하는 인물은 기계화된 우주선 조종사로 구체화된다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"사이보그","entry_url":"cards/ML-T01143/index.html"},{"id":"ML-T01144","row_version":3,"title":"인공지능","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"인공지능은 학습·추론·판단 같은 정보 처리 기능을 수행하는 인공적으로 구현된 지능이다. 소프트웨어나 기계의 기능으로만 존재할 수도 있고 독립된 인격적 개체로 묘사될 때는 인공 존재로도 분류한다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"인공지능","entry_url":"cards/ML-T01144/index.html"},{"id":"ML-T01145","row_version":3,"title":"자동인형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"자동인형은 기계 장치나 태엽·마법적 구동력으로 정해진 동작을 수행하도록 만든 인형형 존재다. 제한된 자동 동작이나 대본화된 반응이 중심이며, 자율적 사고와 독립된 인격을 가진 로봇·안드로이드와 구분한다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"자동인형","entry_url":"cards/ML-T01145/index.html"},{"id":"ML-T01146","row_version":2,"title":"디지털 생명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"디지털 생명은 데이터나 가상 환경 안에서 생명체처럼 지속되고 상호작용하는 존재다. 정보 상태가 존재의 몸과 활동 기반일 때 적용하고, 단순한 프로그램이나 저장된 기록은 생명체적 자율성이 없으면 제외한다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"디지털 생명","entry_url":"cards/ML-T01146/index.html"},{"id":"ML-T01147","row_version":2,"title":"생체 병기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01140","tag_path":[],"summary":"생체 병기는 생물학적 몸이나 생명 기능을 무기 목적으로 설계·개조해 만든 존재다. 전투·살상 용도로 생체가 제작되었거나 조직적으로 변형된 경우를 가리키며, 무기를 든 자연 생명체와 구분한다.","accent":"#62816F","tab":"#7D8FA3","facet":"존재·종족","bookmark":"생체 병기","entry_url":"cards/ML-T01147/index.html"},{"id":"ML-T01148","row_version":2,"title":"외계·이계 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"group","parent_id":"ML-F12","tag_path":[],"summary":"외계·이계 존재는 인간의 세계와 다른 행성·차원·현실 층위에 기원을 둔 존재를 포괄한다. 출신 세계가 핵심 기준이며, 낯설거나 초자연적이라는 인상만으로는 해당하지 않는다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"외계·이계 존재","entry_url":"cards/ML-T01148/index.html"},{"id":"ML-T01149","row_version":2,"title":"외계 생명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"외계 생명은 지구 밖 행성이나 우주 환경에서 기원한 생명체다. 우주적 출신이나 생태가 설정의 근거여야 하며, 다른 차원에서 온 존재와는 기원 세계를 구분한다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"외계 생명","entry_url":"cards/ML-T01149/index.html"},{"id":"ML-T01150","row_version":2,"title":"차원 생명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"차원 생명은 인간이 속한 현실과 다른 차원이나 존재 층위에서 기원한 생명체다. 이계의 물리 법칙이나 환경에 기반할 때 적용하며, 우주 공간의 다른 행성에서 온 생명과 구별한다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"차원 생명","entry_url":"cards/ML-T01150/index.html"},{"id":"ML-T01151","row_version":2,"title":"에너지 생명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"에너지 생명은 고체·액체 같은 물질 신체 대신 에너지 장이나 흐름을 몸의 기반으로 삼는 생명체다. 에너지가 존재의 실체이며 자율적 생명 활동을 할 때 적용하고, 에너지를 사용하는 기계나 비물질 영혼과 구분한다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"에너지 생명","entry_url":"cards/ML-T01151/index.html"},{"id":"ML-T01152","row_version":2,"title":"우주적 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"하나의 행성이나 문명을 넘어 우주 규모에서 행동하거나 위협으로 인식되는 존재를 찾는 분류다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"우주적 존재","entry_url":"cards/ML-T01152/index.html"},{"id":"ML-T01153","row_version":2,"title":"시간 밖의 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"시간 밖의 존재는 통상적인 시간의 흐름이나 인과 관계에 종속되지 않는 존재다. 시간 밖의 관점·존재 방식이 설정에 명시될 때 적용하며, 단순한 장수자나 시간 여행자와 구분한다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"시간 밖의 존재","entry_url":"cards/ML-T01153/index.html"},{"id":"ML-T01154","row_version":2,"title":"추상 개념의 인격화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01148","tag_path":[],"summary":"추상 개념의 인격화는 죽음·전쟁·기억 같은 추상적 관념이 의식과 행위 능력을 갖춘 인물이나 존재로 구현된 경우다. 개념 자체가 존재의 정체성일 때 적용하고, 그 개념을 상징하는 평범한 인물과 구분한다.","accent":"#62816F","tab":"#A07A87","facet":"존재·종족","bookmark":"추상 개념의 인격화","entry_url":"cards/ML-T01154/index.html"},{"id":"ML-T01155","row_version":2,"title":"집합·복합 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"group","parent_id":"ML-F12","tag_path":[],"summary":"집합·복합 존재는 여러 개체나 성분이 결합해 하나의 행위 주체처럼 기능하는 존재다. 단일한 몸이나 의식으로 통합된 작동이 기준이며, 단순히 함께 움직이는 집단과 구분한다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"집합·복합 존재","entry_url":"cards/ML-T01155/index.html"},{"id":"ML-T01156","row_version":2,"title":"군체 생명","original":"Hive life","aliases":["Hive life"],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"군체 생명은 다수의 생물 개체가 연결되어 공동의 생존·감각·행동 체계를 이루는 생명체다. 개체들의 상호 의존이나 집단적 조절이 생명 활동의 핵심일 때 적용하고, 개체성이 유지된 무리나 사회 집단과 구분한다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"군체 생명","entry_url":"cards/ML-T01156/index.html"},{"id":"ML-T01157","row_version":2,"title":"집단지성","original":"Collective intelligence","aliases":["Collective intelligence"],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"여러 개체가 정보를 공유하고 연결망처럼 처리해 하나의 판단이나 의사소통을 이루는 존재 방식이다. 단순히 무리가 함께 행동하는 경우와 구별하고, 개별 구성원의 정보가 집단 차원의 인식으로 통합되는지를 기준으로 삼는다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"집단지성","entry_url":"cards/ML-T01157/index.html"},{"id":"ML-T01158","row_version":2,"title":"융합 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"서로 구별되던 개체나 생명체가 결합해 하나의 몸이나 새로운 개체로 작동하는 존재다. 일시적인 협력이나 동승과 달리 결합 뒤에 개체의 경계나 기능이 실질적으로 바뀌는지 살핀다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"융합 존재","entry_url":"cards/ML-T01158/index.html"},{"id":"ML-T01159","row_version":3,"title":"분열하는 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"하나의 존재가 둘 이상의 개체로 나뉘며, 분리된 개체가 독립적으로 움직이거나 생존하는 방식이다. 복제나 단순한 환영 생성과 구별하려면 분열체가 본체와 어떤 연속성·자율성을 갖는지 확인한다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"분열하는 존재","entry_url":"cards/ML-T01159/index.html"},{"id":"ML-T01160","row_version":2,"title":"기생 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"다른 생명체의 몸이나 내부에 자리 잡고 자원이나 기능을 얻으며 살아가는 존재다. 숙주를 일시적으로 조종하거나 몸에 붙어 있는 것만으로는 부족하며, 지속적인 의존 관계가 설정되어야 한다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"기생 존재","entry_url":"cards/ML-T01160/index.html"},{"id":"ML-T01161","row_version":3,"title":"공생 복합체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01155","tag_path":[],"summary":"서로 다른 개체가 긴밀히 결합해 하나의 생존·행동 단위를 이루는 복합적인 존재다. 한쪽이 다른 쪽을 일방적으로 이용하는 기생 관계와 구별해, 각 구성원이 결합체의 유지나 기능에 어떤 몫을 하는지 본다.","accent":"#62816F","tab":"#79866C","facet":"존재·종족","bookmark":"공생 복합체","entry_url":"cards/ML-T01161/index.html"},{"id":"ML-T01162","row_version":2,"title":"전승 특정 존재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"group","parent_id":"ML-F12","tag_path":[],"summary":"특정 민속·종교·문학 전승에서 이름과 특징이 이어져 온 존재를 가리킨다. 막연한 환상 생물이나 창작 종족은 전승과의 구체적인 연결이 드러날 때만 이 범주에 둔다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"전승 특정 존재","entry_url":"cards/ML-T01162/index.html"},{"id":"ML-T01163","row_version":2,"title":"도깨비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"한국 민간 전승에서 사람과 교류하거나 변신하고, 신묘한 능력과 장난스러운 성격을 보이는 초자연적 존재다. 뿔이나 방망이 같은 한 가지 도상만으로 한정하지 말고, 작품이 한국 도깨비 전승의 특징을 실제로 활용하는지 판단한다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"도깨비","entry_url":"cards/ML-T01163/index.html"},{"id":"ML-T01164","row_version":4,"title":"구미호","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"한국 전승에서 사람으로 변신하거나 사람과 관계를 맺는 여우 정령으로, 흔히 오랜 수련과 신비한 능력이 함께 묘사된다. 여우 모양의 요괴 전반과 구별해 구미호라는 전승적 정체성이나 변신 모티프가 서사에 작동하는지 본다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"구미호","entry_url":"cards/ML-T01164/index.html"},{"id":"ML-T01165","row_version":2,"title":"저승사자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"한국의 사후세계관에서 죽은 이의 혼을 인도하거나 데려가는 임무를 맡은 존재다. 죽음의 신이나 사후세계의 통치자와 혼동하지 말고, 영혼을 안내·인도하는 역할이 설정의 중심인지 확인한다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"저승사자","entry_url":"cards/ML-T01165/index.html"},{"id":"ML-T01166","row_version":2,"title":"선녀","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"한국 설화에서 하늘과 연결된 초월적 여성 존재로, 지상에 내려오거나 인간과 인연을 맺는 이야기로 전해진다. 날개옷이나 천상 출신이라는 장식만으로 붙이지 말고, 선녀 전승의 하강·귀환 또는 인간과의 관계가 쓰이는지 본다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"선녀","entry_url":"cards/ML-T01166/index.html"},{"id":"ML-T01167","row_version":3,"title":"이무기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"동아시아 전승에서 용이 되기 전 단계의 큰 뱀 또는 물속의 영물로 여겨지는 존재다. 단순한 거대 뱀이나 완성된 용과 구별해, 용으로 승천하거나 변할 가능성이 핵심 설정인지 살핀다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"이무기","entry_url":"cards/ML-T01167/index.html"},{"id":"ML-T01168","row_version":3,"title":"엘프","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"서구 신화·판타지 계열에서 인간과 다른 생애와 문화를 지닌 종족으로, 흔히 자연·마법과 가까운 존재로 그려진다. 뾰족한 귀 같은 외형만으로 분류하지 말고, 작품이 엘프라는 전승·장르 관습의 종족 정체성을 활용하는지 본다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"엘프","entry_url":"cards/ML-T01168/index.html"},{"id":"ML-T01169","row_version":3,"title":"드워프","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"서구 전승과 판타지에서 굳세고 기술에 능한 소형 또는 인간형 종족으로 묘사되는 존재다. 지하 거주나 대장 기술만으로 판정하지 말고, 드워프라는 종족 관습과 문화적 정체성이 설정에 포함되는지 확인한다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"드워프","entry_url":"cards/ML-T01169/index.html"},{"id":"ML-T01170","row_version":3,"title":"오크","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"서구 판타지에서 인간형 전사 종족으로 자주 등장하는 존재로, 작품에 따라 야만성·군사 조직·다른 종족과의 갈등이 강조된다. 녹색 피부나 거친 외모만으로 정하지 말고, 오크라는 종족 정체성이 세계관에서 어떤 의미를 갖는지 본다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"오크","entry_url":"cards/ML-T01170/index.html"},{"id":"ML-T01171","row_version":2,"title":"지니","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":"tag","parent_id":"ML-T01162","tag_path":[],"summary":"아랍·이슬람권 전승에서 불과 연기 등으로 창조된 비가시적 존재로, 인간과 다른 의지와 능력을 지닌다. 소원을 들어주는 램프의 정령으로만 축소하지 말고, 작품이 지니 전승의 독립된 존재성과 성격을 반영하는지 살핀다.","accent":"#62816F","tab":"#AF8665","facet":"존재·종족","bookmark":"지니","entry_url":"cards/ML-T01171/index.html"},{"id":"ML-T01172","row_version":2,"title":"현실성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"현실성은 작품 세계가 현실의 물리 법칙과 사회적 조건을 어느 정도 따르는지를 가리킨다. 초자연 요소의 유무만으로 판단하지 말고, 세계의 기본 작동 방식이 현실과 얼마나 맞닿아 있는지 본다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"현실성","entry_url":"cards/ML-T01172/index.html"},{"id":"ML-T01173","row_version":2,"title":"현실 준거 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"현실 준거 세계는 익숙한 현실의 지리·역사·과학 법칙을 바탕으로 삼는 세계다. 비현실적 사건이 등장하더라도 배경의 기본 조건이 현실과 이어지는지 기준으로 삼는다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"현실 준거 세계","entry_url":"cards/ML-T01173/index.html"},{"id":"ML-T01174","row_version":2,"title":"숨겨진 초자연 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"일상 사회와 초자연적 질서가 함께 존재하지만 그 실재가 널리 알려지지 않은 세계다. 은폐의 방법과 두 사회의 접점이 설정의 핵심이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"숨겨진 초자연 세계","entry_url":"cards/ML-T01174/index.html"},{"id":"ML-T01175","row_version":2,"title":"공개된 초자연 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"공개된 초자연 세계에서는 마법이나 초능력 같은 현상이 사회에 알려져 제도와 일상에 영향을 준다. 비밀리에 소수만 접하는 현상이나 개인의 착각만으로 끝나는 사건은 구별한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"공개된 초자연 세계","entry_url":"cards/ML-T01175/index.html"},{"id":"ML-T01176","row_version":3,"title":"독립 판타지 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"독립 판타지 세계는 현실 세계와 별개로 지리·역사·사회가 구성된 허구의 무대다. 현실의 장소에 초자연 요소가 더해진 배경과 달리, 세계 자체가 독자적인 기반을 갖는지 살핀다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"독립 판타지 세계","entry_url":"cards/ML-T01176/index.html"},{"id":"ML-T01177","row_version":3,"title":"시뮬레이션 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"시뮬레이션 세계는 현실처럼 경험되는 환경이 계산·모사된 공간이며, 그 안의 규칙은 프로그램이나 모형에 의해 작동한다. 단순히 기술이 발달한 배경인지, 세계의 실체가 시뮬레이션인지 구분한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"시뮬레이션 세계","entry_url":"cards/ML-T01177/index.html"},{"id":"ML-T01178","row_version":2,"title":"꿈의 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01172","tag_path":[],"summary":"꿈의 세계는 꿈을 꾸는 의식과 연결되어 형성되며, 꿈의 논리나 꿈꾸는 이의 상태에 따라 공간과 사건이 달라질 수 있다. 환상적인 장소라는 이유만으로 붙이지 말고 꿈과의 인과적 연결을 확인한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"꿈의 세계","entry_url":"cards/ML-T01178/index.html"},{"id":"ML-T01179","row_version":3,"title":"세계 층위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"세계 층위는 작품 안에 서로 다른 차원·영역·현실이 몇 겹으로 존재하고 어떤 관계를 맺는지를 뜻한다. 장소가 여러 곳이라는 사실과 존재론적으로 구분되는 세계가 여럿이라는 설정을 구별한다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"세계 층위","entry_url":"cards/ML-T01179/index.html"},{"id":"ML-T01180","row_version":4,"title":"단일 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"단일 세계는 서사의 주요 사건이 하나의 연속된 현실 또는 차원 안에서 벌어지는 구성이다. 지역이나 행성이 여럿이어도 같은 우주와 규칙을 공유하면 단일 세계로 볼 수 있다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"단일 세계","entry_url":"cards/ML-T01180/index.html"},{"id":"ML-T01181","row_version":1,"title":"평행세계","original":"Parallel World","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"서로 다른 상태나 역사를 가진 세계들이 나란히 존재하는 설정이다. 세계 간의 이동 가능성과 분기 원인이 작품마다 달라진다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"평행세계","entry_url":"cards/ML-T01181/index.html"},{"id":"ML-T01182","row_version":2,"title":"다중우주","original":"Multiverse","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"여러 우주가 함께 존재하는 세계 구조다. 우주 사이의 법칙·경계·접촉 가능성이 각각의 설정을 구별한다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"다중우주","entry_url":"cards/ML-T01182/index.html"},{"id":"ML-T01183","row_version":3,"title":"중첩 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"중첩 세계는 한 세계가 다른 세계를 포함하거나, 서로 다른 현실이 층위별로 포개져 있는 구조다. 단순한 은유적 세계관이나 별개의 세계를 오가는 설정과 달리 포함·포개짐의 관계가 실제로 작동해야 한다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"중첩 세계","entry_url":"cards/ML-T01183/index.html"},{"id":"ML-T01184","row_version":3,"title":"포켓 차원","original":"Pocket Dimension","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"현재 세계에 붙어 있으면서 보통 공간보다 더 넓은 내부나 숨겨진 장소를 제공하는 작은 별도 공간. 보관, 피신, 비밀 거주지처럼 쓰인다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/ML-T01184/index.html"},{"id":"ML-T01185","row_version":2,"title":"세계 안의 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01179","tag_path":[],"summary":"세계 안의 세계는 하나의 세계 내부에 독립된 공간·현실이 별도로 존재하는 설정이다. 넓은 지역이나 폐쇄된 장소만으로는 해당하지 않으며, 내부 영역이 별도의 세계처럼 기능하는지 본다.","accent":"#497A73","tab":"#778F70","facet":"세계관·규칙","bookmark":"세계 안의 세계","entry_url":"cards/ML-T01185/index.html"},{"id":"ML-T01186","row_version":3,"title":"시간 규칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"시간 규칙은 작품 세계에서 시간의 흐름과 과거·현재·미래의 관계를 결정하는 원리다. 시간여행이나 회상이 있다는 사실보다 사건이 시간선에 어떤 변화를 허용하는지 확인한다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 규칙","entry_url":"cards/ML-T01186/index.html"},{"id":"ML-T01187","row_version":3,"title":"단일 시간선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"단일 시간선은 과거와 현재, 미래가 하나의 연속된 역사로 이어지는 구조다. 선택이나 시간 이동이 있어도 별도 갈래가 생기지 않는다면 이 기준에 해당한다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"단일 시간선","entry_url":"cards/ML-T01187/index.html"},{"id":"ML-T01188","row_version":2,"title":"분기 시간선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"분기 시간선은 선택이나 사건에 따라 하나의 역사가 둘 이상의 갈래로 나뉘는 구조다. 과거를 바꿔 결과가 달라지는 것만으로는 부족하며, 갈라진 역사들이 별도로 성립하는지 본다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"분기 시간선","entry_url":"cards/ML-T01188/index.html"},{"id":"ML-T01189","row_version":2,"title":"고정된 역사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"고정된 역사는 과거의 사건이 이미 정해져 있어 개입해도 기록된 결과를 벗어나지 못하는 시간 구조다. 시간여행자가 과거에 영향을 주더라도 그 영향 자체가 기존 역사의 일부라면 해당한다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"고정된 역사","entry_url":"cards/ML-T01189/index.html"},{"id":"ML-T01190","row_version":2,"title":"바뀌는 역사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"바뀌는 역사는 과거의 개입이나 특정 사건으로 현재와 미래의 실제 경과가 달라지는 구조다. 인물의 기억이나 기록만 바뀌는 경우와 역사 자체가 수정되는 경우를 나누어 판단한다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"바뀌는 역사","entry_url":"cards/ML-T01190/index.html"},{"id":"ML-T01191","row_version":1,"title":"시간 회귀","original":"Time Regression","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"인물이나 세계의 시간이 이전 시점으로 돌아가는 설정이다. 과거의 기억이 남는지와 이후의 역사가 달라질 수 있는지가 중요한 구분점이다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 회귀","entry_url":"cards/ML-T01191/index.html"},{"id":"ML-T01192","row_version":1,"title":"시간 반복","original":"Time Loop","aliases":["타임 루프","Time Loop"],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"일정한 시간 구간이 되풀이되는 세계의 규칙이다. 반복되는 구간, 기억을 유지하는 존재와 반복을 끝내는 조건에 따라 다른 이야기를 만든다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 반복","entry_url":"cards/ML-T01192/index.html"},{"id":"ML-T01193","row_version":3,"title":"시간 정지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"시간 정지는 특정 영역이나 대상의 시간 흐름을 멈추는 현상이다. 주변이 느려 보이는 효과나 인물의 초고속 이동과 구분해, 대상의 시간 자체가 실제로 멈추는지 본다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간 정지","entry_url":"cards/ML-T01193/index.html"},{"id":"ML-T01194","row_version":2,"title":"시간의 비대칭","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01186","tag_path":[],"summary":"시간의 비대칭은 서로 다른 장소나 인물에게 시간이 동일한 비율로 흐르지 않는 현상이다. 단순한 시차나 편집상의 생략이 아니라, 세계 안에서 체감·경과 시간이 다르게 누적되는지 기준으로 삼는다.","accent":"#497A73","tab":"#8B739C","facet":"세계관·규칙","bookmark":"시간의 비대칭","entry_url":"cards/ML-T01194/index.html"},{"id":"ML-T01195","row_version":2,"title":"인과·운명","original":"Fate And Prophecy","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"인과·운명은 사건의 원인과 결과가 필연성이나 운명에 의해 얼마나 강하게 묶이는지를 다룬다. 우연한 연쇄나 인물의 신념만으로는 부족하며, 인과 또는 운명이 세계의 실제 규칙인지 살핀다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"인과·운명","entry_url":"cards/ML-T01195/index.html"},{"id":"ML-T01196","row_version":2,"title":"예정된 운명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"예정된 운명은 특정 인물이나 사건의 결말이 이미 정해져 있어 벗어나기 어려운 상태다. 불길한 예언이나 강한 예감만으로 단정하지 말고, 선택과 행동이 결말을 바꿀 수 있는지 확인한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"예정된 운명","entry_url":"cards/ML-T01196/index.html"},{"id":"ML-T01197","row_version":2,"title":"바꿀 수 있는 예언","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"바꿀 수 있는 예언은 미래를 가리키는 예언이 인물의 선택이나 대응에 따라 실현되지 않거나 다른 방식으로 성취될 수 있는 구조다. 예언이 이미 확정된 미래를 설명하는지, 변화의 조건을 제공하는지 구별한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"바꿀 수 있는 예언","entry_url":"cards/ML-T01197/index.html"},{"id":"ML-T01198","row_version":1,"title":"자기실현적 예언","original":"Self-Fulfilling Prophecy","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"예언을 알게 된 존재의 행동이 예언된 결과를 일으키는 인과 구조다. 예언을 피하려는 시도가 오히려 실현의 원인이 되는 변형을 포함한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"자기실현적 예언","entry_url":"cards/ML-T01198/index.html"},{"id":"ML-T01199","row_version":3,"title":"확률 조작 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"확률 조작 세계에서는 사건의 가능성이나 우연의 발생률을 초자연적·기술적 규칙으로 바꿀 수 있다. 운이 좋거나 나쁜 결과가 반복되는 묘사와 달리, 확률 자체가 개입 가능한 대상인지 본다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"확률 조작 세계","entry_url":"cards/ML-T01199/index.html"},{"id":"ML-T01200","row_version":2,"title":"인과의 대가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"인과의 대가는 특정 결과를 일으키거나 과거를 바꾼 행위에 별도의 손실·반작용이 뒤따르는 규칙이다. 일반적인 노력이나 능력 사용 비용과 구별해, 대가가 인과 개입에 직접 연결되는지 확인한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"인과의 대가","entry_url":"cards/ML-T01200/index.html"},{"id":"ML-T01201","row_version":2,"title":"서사 법칙의 실재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01195","tag_path":[],"summary":"서사 법칙의 실재는 이야기의 전개 원리나 서사적 역할이 작품 세계 안에서 실제 힘으로 작동하는 설정이다. 등장인물이 이야기를 언급하는 메타 농담만으로는 부족하며, 그 법칙이 사건이나 선택을 구속해야 한다.","accent":"#497A73","tab":"#A58A4E","facet":"세계관·규칙","bookmark":"서사 법칙의 실재","entry_url":"cards/ML-T01201/index.html"},{"id":"ML-T01202","row_version":2,"title":"생사·영혼","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"생사·영혼은 죽음의 상태와 영혼의 존재·이동·지속을 규정하는 세계의 원리다. 죽음에 대한 비유나 종교적 믿음만 있는지, 영혼이나 사후 상태가 사건으로 확인되는지 구분한다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"생사·영혼","entry_url":"cards/ML-T01202/index.html"},{"id":"ML-T01203","row_version":2,"title":"영혼의 실재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"영혼의 실재는 육체와 구별되는 영적 존재나 의식의 핵심이 세계 안에 실제로 존재하는 설정이다. 인격이나 기억을 비유적으로 영혼이라 부르는 경우와 물리적·서사적으로 작용하는 실체를 나눈다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"영혼의 실재","entry_url":"cards/ML-T01203/index.html"},{"id":"ML-T01204","row_version":2,"title":"사후세계의 실재","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"사후세계의 실재는 죽은 자가 도달하거나 머무는 영역이 작품 세계에 실제 장소나 상태로 존재하는 설정이다. 사후세계에 대한 전승이나 인물의 믿음만 제시되는 경우는 실제 존재와 구별한다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"사후세계의 실재","entry_url":"cards/ML-T01204/index.html"},{"id":"ML-T01205","row_version":3,"title":"윤회 규칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"윤회 규칙은 죽음 뒤 영혼이나 존재가 새로운 생으로 이어지는 방식과 조건을 정한다. 환생이 한 차례 일어나는 사건인지, 반복되는 생의 순환이 세계의 원리인지 확인한다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"윤회 규칙","entry_url":"cards/ML-T01205/index.html"},{"id":"ML-T01206","row_version":2,"title":"부활 가능 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"부활 가능 세계는 죽은 존재가 일정한 방법이나 조건을 통해 다시 살아날 수 있는 세계다. 죽음에서 살아남았거나 죽음이 위장된 경우와 실제 사망 뒤의 귀환을 구별한다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"부활 가능 세계","entry_url":"cards/ML-T01206/index.html"},{"id":"ML-T01207","row_version":2,"title":"불멸의 조건","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"불멸의 조건은 늙거나 죽지 않는 상태가 유지되는 조건과 그 상태를 끝낼 수 있는 예외를 정한다. 단순히 장수하는 인물과 죽음이 제한되거나 특정 약점에만 가능한 존재를 나누어 본다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"불멸의 조건","entry_url":"cards/ML-T01207/index.html"},{"id":"ML-T01208","row_version":2,"title":"기억과 자아의 분리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01202","tag_path":[],"summary":"기억과 자아의 분리는 기억의 변화·상실과 인격의 지속성이 서로 독립적으로 다뤄지는 설정이다. 기억상실을 곧 인격 교체로 간주하지 말고, 작품이 자아의 동일성을 무엇으로 판단하는지 본다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"기억과 자아의 분리","entry_url":"cards/ML-T01208/index.html"},{"id":"ML-T01209","row_version":3,"title":"힘의 체계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"힘의 체계는 초자연적·특수한 능력이 어디서 나오고 어떤 방식으로 획득·사용되는지 정한 원리다. 강한 인물이 여럿 등장하는 것만으로는 부족하며, 능력 사이에 반복 가능한 규칙이 있는지 살핀다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"힘의 체계","entry_url":"cards/ML-T01209/index.html"},{"id":"ML-T01210","row_version":3,"title":"마법의 보편화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"마법을 사용할 기회가 소수의 혈통이나 신분에만 묶이지 않고 사회 전반으로 넓어지는 세계의 규칙을 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"마법의 보편화","entry_url":"cards/ML-T01210/index.html"},{"id":"ML-T01211","row_version":2,"title":"마법의 희소성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"마법을 쓸 수 있는 사람이나 마력의 공급이 제한되어 마법이 드문 자원처럼 다뤄지는 세계를 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"마법의 희소성","entry_url":"cards/ML-T01211/index.html"},{"id":"ML-T01212","row_version":3,"title":"신성력 체계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"신성력 체계는 신격이나 성스러운 원천에서 힘이 나오고, 신앙·계약·의식 같은 조건으로 사용되는 구조다. 종교 기관의 권위나 신의 존재만으로는 해당하지 않으며 힘의 발현과 규칙이 연결되어야 한다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"신성력 체계","entry_url":"cards/ML-T01212/index.html"},{"id":"ML-T01213","row_version":2,"title":"초능력 체계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"초능력 체계는 개인의 비범한 정신적·신체적 능력이 일정한 유형과 한계에 따라 작동하는 구조다. 한 번의 기적이나 일반 기술과 구분해 능력의 발현·범위·제약이 반복해서 확인되는지 본다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"초능력 체계","entry_url":"cards/ML-T01213/index.html"},{"id":"ML-T01214","row_version":3,"title":"기술과 마법의 공존","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"기술 장치와 마법이 같은 세계에서 어떤 관계를 맺으며 함께 쓰이는지 찾는 태그다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"기술과 마법의 공존","entry_url":"cards/ML-T01214/index.html"},{"id":"ML-T01215","row_version":2,"title":"능력의 계승","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01209","tag_path":[],"summary":"능력의 계승은 혈통·사제 관계·양도·전승 같은 경로를 통해 힘이 다른 사람에게 이어지는 설정이다. 기술을 배우는 것과 구별해, 계승된 능력이나 힘의 소유권이 실제로 전달되는지 확인한다.","accent":"#497A73","tab":"#7D8FA3","facet":"세계관·규칙","bookmark":"능력의 계승","entry_url":"cards/ML-T01215/index.html"},{"id":"ML-T01216","row_version":2,"title":"세계 질서","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"세계 질서는 사회와 환경이 현재 어떤 안정도와 변화 상태에 놓였는지를 나타낸다. 특정 집단의 일시적 위기보다 세계 전체의 구조와 지속 가능성을 기준으로 판단한다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"세계 질서","entry_url":"cards/ML-T01216/index.html"},{"id":"ML-T01217","row_version":2,"title":"안정된 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"안정된 세계는 사회 제도와 생활 기반이 대체로 유지되어 급격한 붕괴가 진행 중이지 않은 상태다. 갈등이나 범죄가 있더라도 세계 전체의 기본 질서가 지속되는지 살핀다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"안정된 세계","entry_url":"cards/ML-T01217/index.html"},{"id":"ML-T01218","row_version":2,"title":"몰락 중인 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"몰락 중인 세계는 정치·환경·문명 기반이 지속적으로 약화되어 쇠퇴가 진행되는 상태다. 과거의 몰락을 회고하는 배경이나 단일 지역의 재난과 달리, 현재의 하강 추세가 세계에 걸쳐야 한다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"몰락 중인 세계","entry_url":"cards/ML-T01218/index.html"},{"id":"ML-T01219","row_version":2,"title":"종말 직전 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"종말 직전 세계는 임박한 재앙이나 붕괴가 다가와 생존과 대응이 긴급한 상태다. 장기적인 쇠퇴와 구별해, 결정적 파국이 가까운 시점에 닥칠 것으로 설정되는지 본다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"종말 직전 세계","entry_url":"cards/ML-T01219/index.html"},{"id":"ML-T01220","row_version":2,"title":"종말 이후 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"종말 이후 세계는 문명이나 기존 질서를 무너뜨린 대재앙이 이미 지나간 뒤의 환경이다. 재앙이 일어날 것이라는 예고나 진행 중인 위기와 달리, 파국의 결과가 현재 세계의 조건을 이룬다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"종말 이후 세계","entry_url":"cards/ML-T01220/index.html"},{"id":"ML-T01221","row_version":3,"title":"재건 중인 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"재건 중인 세계는 파괴되거나 붕괴한 사회와 생활 기반을 다시 세우는 과정에 놓여 있다. 생존만 이어지는 상태와 구분해, 복구·정착·제도 재구성이 실제 과제로 진행되는지 본다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"재건 중인 세계","entry_url":"cards/ML-T01221/index.html"},{"id":"ML-T01222","row_version":3,"title":"순환하는 문명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01216","tag_path":[],"summary":"순환하는 문명은 문명의 성장과 붕괴, 재출현이 반복되는 역사 구조를 가진 세계다. 왕조 교체나 유사한 사건의 반복보다, 문명 수준의 순환이 세계의 주기적 원리인지 확인한다.","accent":"#497A73","tab":"#A07A87","facet":"세계관·규칙","bookmark":"순환하는 문명","entry_url":"cards/ML-T01222/index.html"},{"id":"ML-T01223","row_version":3,"title":"시스템화된 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"시스템화된 세계는 규칙·수치·기능이 체계로 명시되어 개인의 행동과 세계의 사건을 직접 좌우한다. 게임처럼 보이는 표현이나 점수 표시만으로는 부족하며, 시스템이 세계 안에서 실제 효력을 갖는지 본다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"시스템화된 세계","entry_url":"cards/ML-T01223/index.html"},{"id":"ML-T01224","row_version":3,"title":"레벨이 실재하는 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01223","tag_path":[],"summary":"레벨이 실재하는 세계에서는 경험이나 성취에 따라 인물의 단계가 오르고, 그 변화가 능력이나 지위에 영향을 준다. 단순한 성장의 비유나 게임 속 캐릭터 수치와 구분해 세계 안의 실재 여부를 확인한다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"레벨이 실재하는 세계","entry_url":"cards/ML-T01224/index.html"},{"id":"ML-T01225","row_version":2,"title":"상태창이 보이는 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01223","tag_path":[],"summary":"상태창이 보이는 세계에서는 인물의 능력·수치·조건을 나타내는 정보 화면이 세계 안에서 관측된다. 독자에게만 제시되는 설명 그래픽인지, 등장인물이 실제로 확인하고 활용하는 정보인지 구별한다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"상태창이 보이는 세계","entry_url":"cards/ML-T01225/index.html"},{"id":"ML-T01226","row_version":3,"title":"퀘스트가 주어지는 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01223","tag_path":[],"summary":"퀘스트가 주어지는 세계에서는 시스템이나 권한을 가진 존재가 목표와 조건을 인물에게 부여한다. 자발적으로 세운 계획이나 일반적인 임무와 달리, 세계의 규칙이 과제를 지정하는지 본다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"퀘스트가 주어지는 세계","entry_url":"cards/ML-T01226/index.html"},{"id":"ML-T01227","row_version":3,"title":"던전이 생성되는 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01223","tag_path":[],"summary":"던전이 생성되는 세계에서는 특정 규칙을 가진 탐험·전투 공간이 자연 발생하거나 주기적으로 출현한다. 오래된 지하 유적이나 사람이 만든 시설이 있다는 것만으로는 해당하지 않는다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"던전이 생성되는 세계","entry_url":"cards/ML-T01227/index.html"},{"id":"ML-T01228","row_version":3,"title":"신이 운영하는 게임 세계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01223","tag_path":[],"summary":"신이 운영하는 게임 세계는 신격의 존재가 세계를 게임처럼 설계하거나 규칙·도전·보상을 관리하는 설정이다. 신들이 존재하거나 게임이 실제로 진행된다는 사실만으로는 부족하며 운영 주체와 게임 구조의 연결을 본다.","accent":"#497A73","tab":"#79866C","facet":"세계관·규칙","bookmark":"신이 운영하는 게임 세계","entry_url":"cards/ML-T01228/index.html"},{"id":"ML-T01229","row_version":3,"title":"비용·제약","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"group","parent_id":"ML-F13","tag_path":[],"summary":"비용·제약은 능력이나 행동을 사용할 때 필요한 지불과 발동을 제한하는 조건을 뜻한다. 일반적인 난관이나 실패 가능성과 구분해, 세계 규칙이 사용에 구체적인 대가나 한계를 부과하는지 확인한다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"비용·제약","entry_url":"cards/ML-T01229/index.html"},{"id":"ML-T01230","row_version":2,"title":"등가교환 법칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"등가교환 법칙은 무언가를 얻으려면 그에 상응하는 가치나 자원을 내놓아야 한다는 원리다. 단순한 희생이나 거래가 아니라, 주고받는 가치의 균형이 반복적으로 적용되는 규칙인지 살핀다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"등가교환 법칙","entry_url":"cards/ML-T01230/index.html"},{"id":"ML-T01231","row_version":2,"title":"힘 사용의 대가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"힘 사용의 대가는 능력을 발휘한 뒤 에너지·건강·기억·수명 등 구체적인 손실이 발생하는 조건이다. 능력 획득 비용이나 외부의 보복과 구분해, 사용 행위 자체가 손실을 일으키는지 기준으로 삼는다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"힘 사용의 대가","entry_url":"cards/ML-T01231/index.html"},{"id":"ML-T01232","row_version":3,"title":"금지된 지식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"금지된 지식은 알거나 전하는 행위가 사회적 금기나 초자연적 규칙으로 제한된 정보다. 작품에서는 지식 자체가 처벌·위험·오염을 부르는 설정인지, 단지 권력자가 접근을 통제하는 정보인지 구별해 적용한다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"금지된 지식","entry_url":"cards/ML-T01232/index.html"},{"id":"ML-T01233","row_version":2,"title":"자원 고갈 법칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"자원 고갈 법칙은 마법이나 기술을 사용할 때 에너지·재료 같은 한정된 자원이 줄어들고, 회복이나 보충에도 조건이 따르는 규칙이다. 작품에 적용할 때는 사용량에 따라 실제 자원이 소진되는지 살피고, 일시적 피로나 재사용 대기시간만 있는 경우와 구별한다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"자원 고갈 법칙","entry_url":"cards/ML-T01233/index.html"},{"id":"ML-T01234","row_version":2,"title":"기억 소모 법칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"기억 소모 법칙은 능력이나 행위의 대가로 개인의 기억이 사라지거나 훼손되는 세계의 규칙이다. 작품에서는 기억의 손실이 반복적으로 작동하는 비용인지, 우연한 망각이나 외부의 기억 조작인지 구분한다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"기억 소모 법칙","entry_url":"cards/ML-T01234/index.html"},{"id":"ML-T01235","row_version":2,"title":"균형 유지 법칙","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":"tag","parent_id":"ML-T01229","tag_path":[],"summary":"균형 유지 법칙은 힘·자원·질서의 한쪽이 커지면 다른 쪽의 변화나 반작용이 뒤따라 총체적 균형을 맞추는 규칙이다. 작품에 적용할 때는 그 보정이 세계의 일관된 인과 원리인지 확인하고, 단순한 우연이나 도덕적 응보와 구별한다.","accent":"#497A73","tab":"#AF8665","facet":"세계관·규칙","bookmark":"균형 유지 법칙","entry_url":"cards/ML-T01235/index.html"},{"id":"ML-T01236","row_version":2,"title":"시대 구간","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"group","parent_id":"ML-F14","tag_path":[],"summary":"시간의 위치를 큰 역사적·미래적 범위로 가리키는 기준이다. 특정 연도를 알 수 없어도 작품이 어느 시대권을 전제하는지 분명할 때 적용한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"시대 구간","entry_url":"cards/ML-T01236/index.html"},{"id":"ML-T01237","row_version":2,"title":"선사 배경","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"tag","parent_id":"ML-T01236","tag_path":[],"summary":"문자 기록과 국가 체계가 자리 잡기 전의 인류 과거를 배경으로 삼는다. 고고학적 생활상이나 수렵·채집 사회가 중심일 때 쓰고, 단지 오래된 분위기만으로는 분류하지 않는다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"선사 배경","entry_url":"cards/ML-T01237/index.html"},{"id":"ML-T01238","row_version":2,"title":"고대 배경","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":"tag","parent_id":"ML-T01236","tag_path":[],"summary":"고대 문명과 초기 국가가 형성된 역사적 시기를 배경으로 한다. 도시·왕국·고전 문명권이 작품의 시대상을 규정할 때 적용하며, 막연한 고대풍 환상과 구별한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"고대 배경","entry_url":"cards/ML-T01238/index.html"}]}.cards;